import{Tt as e,at as t,s as n,st as r}from"./chunks/framework.EA-f9P_2.js";var i=JSON.parse(`{"title":"React Pro Components Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md","lastUpdated":1787631951000}`),a={name:`en/guide/compatibility.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r('<h1 id="react-pro-components-compatibility" tabindex="-1">React Pro Components Compatibility <a class="header-anchor" href="#react-pro-components-compatibility" aria-label="Permalink to &quot;React Pro Components Compatibility&quot;">​</a></h1><p>The compatibility baseline is <code>@ant-design/pro-components@2.8.10</code>. The goal is a near-complete Vue 3 mapping of the core types and workflows, not React runtime compatibility.</p><p>Status: <span class="compat-ok">supported</span>, <span class="compat-map">Vue mapping</span>, <span class="compat-partial">initial boundary</span>.</p><h2 id="core-mapping" tabindex="-1">Core mapping <a class="header-anchor" href="#core-mapping" aria-label="Permalink to &quot;Core mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">supported</span></td><td>Shared by all three components</td></tr><tr><td><code>request(params, sort, filter)</code></td><td>Same Promise contract</td><td><span class="compat-ok">supported</span></td><td>Returns <code>{ data, total?, success? }</code></td></tr><tr><td><code>actionRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td><td>Similar instance method names</td></tr><tr><td><code>formRef</code> / <code>editableFormRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td><td>React ref props are not retained</td></tr><tr><td><code>value</code> / <code>onChange</code></td><td><code>v-model</code></td><td><span class="compat-map">Vue mapping</span></td><td>Standard <code>update:*</code> events</td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue mapping</span></td><td>Shared single/multiple edit state</td></tr><tr><td>ReactNode props</td><td>Named slots / render callbacks</td><td><span class="compat-map">Vue mapping</span></td><td>Templates first, callbacks when reusable</td></tr><tr><td><code>onRequestError</code></td><td><code>request-error</code></td><td><span class="compat-map">Vue mapping</span></td><td>Existing rows are preserved</td></tr></tbody></table><h2 id="search-collapse" tabindex="-1">Search collapse <a class="header-anchor" href="#search-collapse" aria-label="Permalink to &quot;Search collapse&quot;">​</a></h2><p><code>ProTable.search</code> keeps the core React semantics:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behavior</th></tr></thead><tbody><tr><td><code>defaultCollapsed</code></td><td>Initializes uncontrolled collapse state only</td></tr><tr><td><code>collapsed</code></td><td>Controlled state; the parent updates it</td></tr><tr><td><code>span</code></td><td>Search item grid span; defaults to <code>8</code>, or three fields per row</td></tr><tr><td><code>labelWidth</code></td><td>Numbers are pixels; <code>auto</code> keeps intrinsic sizing</td></tr><tr><td><code>searchText</code> / <code>resetText</code></td><td>Search and reset labels</td></tr><tr><td><code>onCollapse(next)</code></td><td>Collapse-state callback</td></tr></tbody></table><p>Vue also emits <code>search-collapse</code>:</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ProTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ collapsed, span: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search-collapse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">collapsed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $event</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Collapsed mode renders the first row only. The expand/collapse control appears only when more fields exist.</p><h2 id="named-slots" tabindex="-1">Named slots <a class="header-anchor" href="#named-slots" aria-label="Permalink to &quot;Named slots&quot;">​</a></h2><p>Column slot names use <code>column.key</code> first and <code>dataIndex</code> otherwise. Array paths are dot-joined, so <code>[&#39;profile&#39;, &#39;name&#39;]</code> becomes <code>profile.name</code>.</p><table tabindex="0"><thead><tr><th>Component</th><th>Slot</th><th>Slot props</th></tr></thead><tbody><tr><td>ProTable</td><td><code>toolbar-title</code>, <code>toolbar-actions</code></td><td>Toolbar content</td></tr><tr><td>ProTable</td><td><code>header-${columnKey}</code></td><td><code>{ column }</code></td></tr><tr><td>ProTable</td><td><code>cell-${columnKey}</code> or <code>${columnKey}</code></td><td><code>{ value, record, index, column, editable }</code></td></tr><tr><td>SchemaForm</td><td><code>field-${path}</code>, <code>${path}</code>, or the column <code>key</code></td><td><code>{ value, record, column, dependencies, update }</code></td></tr><tr><td>SchemaForm</td><td><code>label-${path}</code></td><td><code>{ column, record }</code></td></tr><tr><td>SchemaForm</td><td><code>submitter</code></td><td><code>{ values, current }</code></td></tr></tbody></table><p>Other slots not consumed by ProTable are forwarded to the underlying Antdv Next Table.</p><h2 id="valuetype-support" tabindex="-1"><code>valueType</code> support <a class="header-anchor" href="#valuetype-support" aria-label="Permalink to &quot;`valueType` support&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Types</th><th>ProTable / EditableProTable</th><th>SchemaForm</th></tr></thead><tbody><tr><td>Text</td><td><code>text</code>, <code>textarea</code>, <code>password</code></td><td>Input, Textarea, Password search/edit controls and formatted display</td><td>Input, Textarea, Password</td></tr><tr><td>Numeric</td><td><code>digit</code>, <code>money</code>, <code>percent</code></td><td>Numeric search and inline InputNumber</td><td>InputNumber with money/percent affordances</td></tr><tr><td>Choices</td><td><code>select</code>, <code>radio</code></td><td>Select / Radio search and editing with <code>valueEnum</code></td><td>Select and Radio</td></tr><tr><td>State</td><td><code>checkbox</code>, <code>switch</code></td><td>Inline Checkbox / Switch</td><td>Checkbox(Group) / Switch</td></tr><tr><td>Date/time</td><td><code>date</code>, <code>dateTime</code>, <code>dateRange</code>, <code>dateTimeRange</code>, <code>time</code>, <code>timeRange</code></td><td>Matching date/time controls and formatted display</td><td>Date/time controls except <code>timeRange</code></td></tr><tr><td>Table</td><td><code>index</code>, <code>indexBorder</code>, <code>option</code></td><td>Index and action columns</td><td>No field generated</td></tr><tr><td>Composition</td><td><code>group</code>, <code>formList</code>, <code>formSet</code>, <code>divider</code>, <code>dependency</code></td><td>No data column generated</td><td>Groups, dynamic lists, sets, dividers, and dependencies</td></tr></tbody></table><h2 id="protable-capabilities" tabindex="-1">ProTable capabilities <a class="header-anchor" href="#protable-capabilities" aria-label="Permalink to &quot;ProTable capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Local/remote data, search, pagination, sort, filters</td><td><span class="compat-ok">supported</span></td><td>Last request wins</td></tr><tr><td>Column visibility, order, fixed state, persistence</td><td><span class="compat-ok">supported</span></td><td>The built-in panel controls visibility only; programmatic <code>columnsState</code> controls and persists <code>order</code> / <code>fixed</code></td></tr><tr><td>Reload, density, fullscreen, row selection</td><td><span class="compat-ok">supported</span></td><td>Options, events, and instance API</td></tr><tr><td>Polling, focus revalidation, manual initial request</td><td><span class="compat-ok">supported</span></td><td><code>polling</code> / <code>revalidateOnFocus</code> / <code>manualRequest</code></td></tr><tr><td>Single, multiple, creator, and tree editing</td><td><span class="compat-ok">supported</span></td><td>Shared with EditableProTable</td></tr><tr><td>React-only DOM and portal props</td><td><span class="compat-partial">not ported</span></td><td>Use Vue slots and Antdv Next props</td></tr></tbody></table><h2 id="editableprotable-mapping" tabindex="-1">EditableProTable mapping <a class="header-anchor" href="#editableprotable-mapping" aria-label="Permalink to &quot;EditableProTable mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>Status</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>v-model:value</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>controlled</code></td><td>Standard <code>v-model</code> semantics</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>recordCreatorProps</code></td><td><code>record</code>, <code>position</code>, <code>parentKey</code>, <code>newRecordType</code>, <code>creatorButtonText</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>maxLength</code></td><td><code>maxLength</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>onValuesChange</code></td><td>Same prop or <code>values-change</code> event</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>onTableChange</code></td><td>Same prop or <code>table-change</code> event</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>editableFormRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td></tr></tbody></table><p><code>value</code> is the only controlled whole-table data entry point; a conflicting <code>dataSource</code> prop is intentionally not exposed.</p><h2 id="schemaform-mapping" tabindex="-1">SchemaForm mapping <a class="header-anchor" href="#schemaform-mapping" aria-label="Permalink to &quot;SchemaForm mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>React SchemaForm</th><th>Vue SchemaForm</th><th>Status</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>layoutType</code></td><td><code>layoutType</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>Form</code> / <code>Embed</code></td><td>Same layouts</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>ModalForm</code> / <code>DrawerForm</code></td><td>Same layouts + <code>v-model:open</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>QueryFilter</code> / <code>LightFilter</code></td><td>Same layouts</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>StepForm</code> / <code>StepsForm</code></td><td>Same layouts + <code>v-model:current</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>group</code> / <code>formList</code> / <code>formSet</code></td><td>Same <code>valueType</code> values</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>dependency</code></td><td><code>dependencies</code> plus a dependency column</td><td><span class="compat-ok">supported</span></td></tr></tbody></table><p><code>urlSync</code> is a Vue-side extension. <code>true</code> writes fields into query parameters, <code>{ key: &#39;filters&#39; }</code> stores the complete model as JSON in one parameter, and <code>{ mode: &#39;hash&#39; }</code> targets the hash. Browser history navigation hydrates the form again.</p><h2 id="component-refs" tabindex="-1">Component refs <a class="header-anchor" href="#component-refs" aria-label="Permalink to &quot;Component refs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Methods</th></tr></thead><tbody><tr><td>ProTable</td><td><code>reload</code>, <code>reset</code>, <code>setPageInfo</code>, <code>clearSelected</code>, <code>fullScreen</code>, <code>scrollTo</code>, <code>startEditable</code>, <code>saveEditable</code>, <code>cancelEditable</code>, <code>addEditRecord</code></td></tr><tr><td>EditableProTable</td><td>ProTable methods + <code>getRowData</code>, <code>getRowsData</code>, <code>setRowData</code></td></tr><tr><td>SchemaForm</td><td><code>validate</code>, <code>reset</code>, <code>getFieldsValue</code>, <code>setFieldsValue</code>, <code>submit</code>, <code>open</code>, <code>close</code>, <code>next</code>, <code>prev</code></td></tr></tbody></table><h2 id="project-release-convention" tabindex="-1">Project release convention <a class="header-anchor" href="#project-release-convention" aria-label="Permalink to &quot;Project release convention&quot;">​</a></h2><p>Changesets and GitHub Actions are project conventions, not React APIs. Describe npm-facing changes with <code>pnpm changeset</code>. Successful CI on <code>main</code> maintains the version PR; npm publishing only runs when <code>NPM_TOKEN</code> exists, with provenance enabled.</p><h2 id="explicitly-out-of-scope" tabindex="-1">Explicitly out of scope <a class="header-anchor" href="#explicitly-out-of-scope" aria-label="Permalink to &quot;Explicitly out of scope&quot;">​</a></h2><p>The initial release does not include ProLayout, ProCard, ProList, or ProDescriptions and does not depend on a request library. The network boundary is the generic Promise <code>request</code> callback.</p>',31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};